#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        vector<int> r;
        for(int i=n-y;i<n;i++) r.push_back(p[i]);
        for(int i=x;i<n-y;i++) r.push_back(p[i]);
        for(int i=0;i<x;i++) r.push_back(p[i]);
        p=r; ops.push_back({x,y});
    };
    // Selection sort: place element i+1 at position i
    for(int i=0;i<n-1;i++){
        int pos=-1;
        for(int j=i;j<n;j++) if(p[j]==i+1){pos=j;break;}
        if(pos==i) continue;
        // Move to front if not there
        if(pos>0 && pos<n-1){apply(pos,1);pos=n-1;}// puts it at end after: C=p[n-1],B=p[pos..n-2],A=p[0..pos-1]->elem at pos goes to... 
        // Ugh, let me just simulate
        // Retry: move pos to 0
        while(pos!=i){
            if(pos==0){
                // move from 0 to i: x=i+1,y=max(1,1). need x+y<=n-1 and mid nonempty
                int y=min((int)(n-1-i-1),n-1-(i+1));
                if(y<1) y=1;
                if(i+1+y<=n-1){apply(i+1,y);pos=n-y+i;/* not sure */break;}
            }
            // move closer to i by 1
            if(pos>=2 && pos<=n-2){apply(pos,1);/* C=last1,B=p[pos..n-2],A=p[0..pos-1] => elem was at pos, now at 1 */pos=1;}
            if(pos==1 && n>=3){apply(1,1);pos=n-2;}
            if(pos==n-1 && i+1<=n-2){apply(i+1,n-1-i);pos=i;break;}
            if(pos==n-1 && i+1>n-2) break;
            if(pos==0 && i==0) break;
            break;
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
